mapper.select:
SELECT 
FROM face_feature f
LEFT JOIN hr_employee e ON e.id = f.employee_id
WHERE f.employee_id = #{employeeId}
  AND f.provider    = #{provider}
  AND f.status      = 1

mapper.update:
UPDATE face_feature
SET status = 0
WHERE employee_id = #{employeeId}
  AND provider    = #{provider}
